	if !v.Blocked.IsNull() && !v.Blocked.IsUnknown() {
		blocked = types.ObjectValueMust(
			BlockedValue{}.AttributeTypes(ctx),
			v.Blocked.Attributes(),
		)
	}

	attributeTypes := map[string]attr.Type{
		"blocked": basetypes.ObjectType{
			AttrTypes: BlockedValue{}.AttributeTypes(ctx),
		},
		"max_observation_date": basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"blocked":              blocked,
			"max_observation_date": v.MaxObservationDate,
		})

	return objVal, diags
